CREATE OR REPLACE FUNCTION public.war_satchel_funded_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'funded War Satchel financial receipts and journals are immutable';
END;
$function$
CREATE OR REPLACE FUNCTION public.war_satchel_funded_reservation_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF (NEW.id, NEW.owner_user_id, NEW.execution_id, NEW.amount_uwolo,
      NEW.ticket_request_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.owner_user_id, OLD.execution_id, OLD.amount_uwolo,
      OLD.ticket_request_id, OLD.created_at) THEN
    RAISE EXCEPTION 'funded War Satchel reservation economic identity immutable';
  END IF;
  IF (OLD.status='reserved' AND NEW.status NOT IN ('reserved','unknown_hold','released'))
     OR (OLD.status='unknown_hold' AND NEW.status NOT IN ('unknown_hold','committed'))
     OR (OLD.status IN ('committed','released') AND NEW.status <> OLD.status) THEN
    RAISE EXCEPTION 'illegal funded War Satchel reservation state transition';
  END IF;
  IF NEW.status <> 'committed' AND (NEW.ticket_id IS NOT NULL OR NEW.tx_hash IS NOT NULL) THEN
    RAISE EXCEPTION 'uncommitted funded reservation cannot claim a settled ticket';
  END IF;
  IF OLD.status='committed' AND
     (NEW.ticket_id, NEW.tx_hash) IS DISTINCT FROM (OLD.ticket_id, OLD.tx_hash) THEN
    RAISE EXCEPTION 'settled funded ticket identity immutable';
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.war_satchel_native_source_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE owner_id integer; linked_hash varchar(64); linked_ticket integer;
  linked_status varchar(24);
BEGIN
 SELECT a.owner_user_id, b.tx_hash, r.ticket_id, r.status
 INTO owner_id, linked_hash, linked_ticket, linked_status
 FROM public.war_satchel_wager_authorizations a
 JOIN public.war_satchel_wager_broadcasts b ON b.operation_id=a.operation_id
 JOIN public.war_satchel_funded_reservations r ON r.id=a.reservation_id
 WHERE a.operation_id=NEW.wager_operation_id FOR SHARE OF a,b,r;
 IF owner_id IS DISTINCT FROM NEW.owner_user_id
    OR linked_hash IS DISTINCT FROM NEW.funding_tx_hash
    OR linked_ticket IS DISTINCT FROM NEW.ticket_id
    OR linked_status IS DISTINCT FROM 'committed'
    OR NOT EXISTS (
      SELECT 1 FROM public.war_satchel_funded_reservations
      WHERE ticket_request_id=NEW.wager_operation_id
        AND amount_uwolo=NEW.funded_amount_uwolo
        AND tx_hash=NEW.funding_tx_hash
    ) THEN
   RAISE EXCEPTION 'C02_AUTHENTICATED_FRESH_WAGER_FUNDING_REQUIRED';
 END IF;
 RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.war_satchel_wager_authority_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.war_satchel_funded_reservations; a public.war_satchel_wager_authorizations;
BEGIN
 IF TG_TABLE_NAME='war_satchel_wager_authorizations' THEN
  SELECT * INTO STRICT r FROM public.war_satchel_funded_reservations WHERE id=NEW.reservation_id FOR UPDATE;
  IF r.status<>'reserved' OR r.owner_user_id<>NEW.owner_user_id OR r.ticket_request_id<>NEW.operation_id
    OR (NEW.snapshot_json->>'ownerUserId')::integer IS DISTINCT FROM r.owner_user_id
    OR (NEW.snapshot_json->>'executionId')::integer IS DISTINCT FROM r.execution_id
    OR NEW.snapshot_json->>'reservationId' IS DISTINCT FROM r.id
    OR NEW.snapshot_json->>'operationId' IS DISTINCT FROM r.ticket_request_id
    OR NEW.snapshot_json->>'amountUwolo' IS DISTINCT FROM r.amount_uwolo::text THEN
   RAISE EXCEPTION 'wager authorization is not the durable owner reserve';
  END IF;
 ELSE
  SELECT * INTO STRICT a FROM public.war_satchel_wager_authorizations WHERE operation_id=NEW.operation_id;
  SELECT * INTO STRICT r FROM public.war_satchel_funded_reservations WHERE id=a.reservation_id FOR UPDATE;
  IF TG_TABLE_NAME='war_satchel_wager_approvals' AND r.status<>'reserved' THEN
   RAISE EXCEPTION 'review cannot authorize an attempted or released wager';
  END IF;
  IF TG_TABLE_NAME='war_satchel_wager_broadcasts' AND
    (r.status<>'unknown_hold' OR NOT EXISTS(SELECT 1 FROM public.war_satchel_wager_approvals WHERE operation_id=NEW.operation_id)) THEN
   RAISE EXCEPTION 'broadcast candidate requires durable attempt fence and review';
  END IF;
 END IF;
 RETURN NEW;
END $function$
